class Solution:
    def firstDayBeenInAllRooms(self, nextVisit: List[int]) -> int:
        n = len(nextVisit)
        visits = [0] * n
        i, day = 0, 0
        while i < n - 1:
            visits[i] += 1
            if visits[i] % 2 == 1:
                i = nextVisit[i]
            else:
                i += 1
            day += 1
        return day

