class Solution {
public:
    int firstDayBeenInAllRooms(vector<int>& nextVisit) {
        int n = nextVisit.size();
        vector<long long> vis(n, 0);
        long long day = 0;
        int i = 0;
        while (i < n - 1) {
            vis[i]++;
            i = vis[i] % 2 == 1 ? nextVisit[i] : i + 1;
            day++;
        }
        return (int)day;
    }
};

