    int firstDayBeenInAllRooms(vector<int>& nextVisit) {
        const long long MOD = 1e9 + 7;
        int n = nextVisit.size();
        vector<long long> f(n, 0);
        for (int i = 1; i < n; i++)
            f[i] = (2 * f[i - 1] - f[nextVisit[i - 1]] + 2 + 2 * MOD) % MOD;
        return (int)f[n - 1];
    }
};

